import{_ as a,c as e,a2 as i,o as r}from"./chunks/framework.CO0qOYmW.js";const u=JSON.parse('{"title":"AI 应用架构概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/07-application-architecture/01-application/01-overview.md","filePath":"ai/07-application-architecture/01-application/01-overview.md","lastUpdated":1783608971000}'),o={name:"ai/07-application-architecture/01-application/01-overview.md"};function l(d,t,n,c,h,s){return r(),e("div",null,t[0]||(t[0]=[i('<h1 id="ai-应用架构概述" tabindex="-1">AI 应用架构概述 <a class="header-anchor" href="#ai-应用架构概述" aria-label="Permalink to &quot;AI 应用架构概述&quot;">​</a></h1><p>AI 应用架构关注如何把模型、知识、上下文、工具和业务系统组合成真实可用的产品能力。它需要同时处理前端交互、后端服务、任务队列、文件处理、权限认证、系统集成和运行治理。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>面向产品形态</strong>：覆盖 Chatbot、Copilot、智能搜索、文档自动化和业务助手。</li><li><strong>面向系统集成</strong>：把 AI 能力接入 OA、CRM、IM、知识库和内部业务系统。</li><li><strong>面向工程架构</strong>：设计前端流式交互、后端会话管理、任务队列和文件存储。</li></ul><h2 id="架构视角" tabindex="-1">架构视角 <a class="header-anchor" href="#架构视角" aria-label="Permalink to &quot;架构视角&quot;">​</a></h2><table tabindex="0"><thead><tr><th>视角</th><th>说明</th></tr></thead><tbody><tr><td>应用形态</td><td>明确 AI 应用是问答、搜索、助手、自动化还是业务协同</td></tr><tr><td>前端交互</td><td>处理流式输出、会话状态、上传反馈、中断和重新生成</td></tr><tr><td>后端服务</td><td>管理会话、任务、文件、权限、API 和模型调用</td></tr><tr><td>企业集成</td><td>接入组织权限、审计日志、插件体系和业务数据同步</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先识别不同 AI 应用形态的价值和边界。</li><li>再从前端和后端两个方向拆解工程架构。</li><li>最后学习企业系统集成和框架选型，形成可交付的 AI 应用方案。</li></ol>',8)]))}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
